import { View, Text, TextInput, StyleSheet } from "react-native";
import { useState } from "react";
import { registerRootComponent } from "expo";

function App() {
  const [email, setEmail] = useState("");
  const [pass, setPass] = useState("");
  return (
    <View style={styles.screen}>
      <Text style={styles.title}>Нэвтрэх</Text>
      <TextInput nativeID="email" style={styles.input} placeholder="И-мэйл"
        value={email} onChangeText={setEmail} />
      <TextInput nativeID="pass" style={styles.input} placeholder="Нууц үг"
        value={pass} onChangeText={setPass} />
      {/* энд бичнэ үү: email-д email-address гар, pass-д secureTextEntry нэм */}
    </View>
  );
}

const styles = StyleSheet.create({
  screen: { flex: 1, padding: 24, gap: 12, justifyContent: "center" },
  title: { fontSize: 22, fontWeight: "bold", marginBottom: 8 },
  input: { borderWidth: 1, borderColor: "#cbd5e1", borderRadius: 10, padding: 14 },
});

registerRootComponent(App);

import { View, Text, TextInput, StyleSheet } from "react-native";
import { useState } from "react";
import { registerRootComponent } from "expo";

function App() {
  const [email, setEmail] = useState("");
  const [pass, setPass] = useState("");
  return (
    <View style={styles.screen}>
      <Text style={styles.title}>Нэвтрэх</Text>
      <TextInput nativeID="email" style={styles.input} placeholder="И-мэйл"
        keyboardType="email-address" value={email} onChangeText={setEmail} />
      <TextInput nativeID="pass" style={styles.input} placeholder="Нууц үг"
        secureTextEntry value={pass} onChangeText={setPass} />
    </View>
  );
}

const styles = StyleSheet.create({
  screen: { flex: 1, padding: 24, gap: 12, justifyContent: "center" },
  title: { fontSize: 22, fontWeight: "bold", marginBottom: 8 },
  input: { borderWidth: 1, borderColor: "#cbd5e1", borderRadius: 10, padding: 14 },
});

registerRootComponent(App);
